def test_parse_unified_diff_multi_file_multi_hunk(): diff = '\n'.join(['diff --git a/common/pkg/mod.py b/common/pkg/mod.py', 'index 1111111..2222222 100644', '--- a/common/pkg/mod.py', '+++ b/common/pkg/mod.py', '@@ -10,2 +12,3 @@ def foo():', '+a = 1', '+b = 2', '+c = 3', '@@ -40 +45,2 @@ def bar():', '+d = 4', '+e = 5', 'diff --git a/tools/new_tool.py b/tools/new_tool.py', 'new file mode 100644', 'index 0000000..3333333', '--- /dev/null', '+++ b/tools/new_tool.py', '@@ -0,0 +1,2 @@', '+import sys', '+print(sys.argv)', '']); assert dc.parse_unified_diff(diff) == {'common/pkg/mod.py': {12, 13, 14, 45, 46}, 'tools/new_tool.py': {1, 2}}; _m1_diff = '\n'.join(['--- a/common/x.py', '+++ b/common/x.py', '@@ -3 +7 @@', '+changed = True', '']); assert dc.parse_unified_diff(_m1_diff) == {'common/x.py': {7}}; _m2_diff = '\n'.join(['--- "a/common/spaced name.py"', '+++ "b/common/spaced name.py"', '@@ -1 +1 @@', '+x = 1', '--- common/noprefix.py', '+++ common/noprefix.py', '@@ -1 +2 @@', '+y = 2', '']); assert dc.parse_unified_diff(_m2_diff) == {'common/spaced name.py': {1}, 'common/noprefix.py': {2}}; _m3_diff = '\n'.join(['--- a/common/x.py', '+++ b/common/x.py', '@@ -5,3 +4,0 @@', '-gone = 1', '-gone = 2', '-gone = 3', '']); assert dc.parse_unified_diff(_m3_diff) == {}; _m4_diff = '\n'.join(['diff --git a/common/old.py b/common/old.py', 'deleted file mode 100644', '--- a/common/old.py', '+++ /dev/null', '@@ -1,3 +0,0 @@', '-x = 1', '-y = 2', '-z = 3', 'diff --git a/common/before.py b/common/after.py', 'similarity index 100%', 'rename from common/before.py', 'rename to common/after.py', '']); assert dc.parse_unified_diff(_m4_diff) == {}; _m5_resolved = dc.resolve_component('apps/backend/src/services/foo.py'); assert _m5_resolved is not None; _m5_component, _m5_relative = _m5_resolved; assert _m5_component.name == 'backend'; assert _m5_relative == 'src/services/foo.py'; _m5_resolved = dc.resolve_component('common/testing/coverage/diff_coverage.py'); assert _m5_resolved is not None; assert _m5_resolved[0].name == 'common'; assert _m5_resolved[1] == 'common/testing/coverage/diff_coverage.py'; _m5_resolved = dc.resolve_component('tools/check_diff_coverage.py'); assert _m5_resolved is not None; assert _m5_resolved[0].name == 'tools'; _m5_resolved = dc.resolve_component('apps/frontend/src/lib/api.ts'); assert _m5_resolved is not None; assert _m5_resolved[0].name == 'frontend'; assert _m5_resolved[1] == 'src/lib/api.ts'; assert dc.resolve_component('common/testing/coverage.md') is None; assert dc.resolve_component('tests/tooling/test_diff_coverage.py') is None; assert dc.resolve_component('.github/workflows/ci.yml') is None; assert dc.resolve_component('apps/backend/src/notes.txt') is None; assert dc.resolve_component('apps/backend/src/__init__.py') is None; assert dc.resolve_component('apps/backend/README.md') is None; assert dc.resolve_component('common/testing/__init__.py') is None; assert dc.resolve_component('apps/frontend/src/__tests__/page.test.tsx') is None; assert dc.format_line_ranges([45, 46, 47, 48, 92]) == '45-48, 92'; assert dc.format_line_ranges([7]) == '7'; assert dc.format_line_ranges([3, 1, 2, 9]) == '1-3, 9'; assert dc.format_line_ranges([]) == ''
def test_parse_lcov_line_hits_sums_duplicates_and_normalizes_paths(tmp_path): lcov = tmp_path / 'common.lcov'; lcov.write_text('\n'.join(['SF:common/pkg/mod.py', 'DA:1,1', 'DA:2,0', 'DA:5,3', 'end_of_record', 'SF:common/pkg/mod.py', 'DA:2,2', 'DA:9,0', 'DA:bad,1', 'DA:7', 'end_of_record'])); component = dc.get_component('common'); hits = dc.parse_lcov_line_hits(lcov, component, tmp_path); assert hits == {'common/pkg/mod.py': {1: 1, 2: 2, 5: 3, 9: 0}}; _m7_tmp = tmp_path / '_m7'; _m7_tmp.mkdir(exist_ok=True); _m7_component = dc.get_component('common'); assert dc.parse_lcov_line_hits(_m7_tmp / 'no.lcov', _m7_component, _m7_tmp) == {}; _m8_tmp = tmp_path / '_m8'; _m8_tmp.mkdir(exist_ok=True); _common_lcov(_m8_tmp, '\n'.join(['SF:common/pkg/mod.py', 'DA:10,1', 'DA:11,0', 'DA:13,2', 'end_of_record', ''])); _m8_report = dc.evaluate_diff_coverage({'common/pkg/mod.py': {10, 11, 12, 13}}, _m8_tmp); assert _m8_report.skipped_components == (); assert len(_m8_report.files) == 1; _m8_verdict = _m8_report.files[0]; assert _m8_verdict.path == 'common/pkg/mod.py'; assert _m8_verdict.component == 'common'; assert _m8_verdict.covered_lines == (10, 13); assert _m8_verdict.uncovered_lines == (11,); assert _m8_verdict.missing_from_lcov is False; assert _m8_report.measurable_lines == 3; assert _m8_report.covered_count == 2; _m9_tmp = tmp_path / '_m9'; _m9_tmp.mkdir(exist_ok=True); _common_lcov(_m9_tmp, 'SF:common/pkg/other.py\nDA:1,1\nend_of_record\n'); _write(_m9_tmp, 'common/pkg/newmod.py', '\n'.join(['"""Docstring."""', '', '# a comment', 'import sys', '', 'print(sys.argv)'])); _m9_report = dc.evaluate_diff_coverage({'common/pkg/newmod.py': {1, 2, 3, 4, 5, 6, 99}, 'common/pkg/untouched.py': set()}, _m9_tmp); assert len(_m9_report.files) == 1; _m9_verdict = _m9_report.files[0]; assert _m9_verdict.missing_from_lcov is True; assert _m9_verdict.covered_lines == (); assert _m9_verdict.uncovered_lines == (1, 4, 6); assert _m9_report.measurable_lines == 3; assert _m9_report.covered_count == 0; _m10_tmp = tmp_path / '_m10'; _m10_tmp.mkdir(exist_ok=True); assert dc._significant_lines(_m10_tmp, {2, 1}) == (1, 2)
def _write(root: Path, rel: str, content: str) -> Path: path = root / rel; path.parent.mkdir(parents=True, exist_ok=True); path.write_text(content); return path
def _common_lcov(root: Path, records: str) -> None: _write(root, 'coverage/common.lcov', records)
def test_out_of_scope_files_and_absent_artifacts_are_lenient(tmp_path, capfd): 'AC-testing.diff-coverage.3'; _write(tmp_path, 'tools/some_tool.py', 'x = 1\n'); changed = {'common/testing/coverage.md': {1, 2}, 'tests/tooling/test_something.py': {5}, '.github/workflows/ci.yml': {100}, 'tools/some_tool.py': {1}}; report = dc.evaluate_diff_coverage(changed, tmp_path); assert report.files == (); assert report.skipped_components == ('tools',); assert report.measurable_lines == 0; assert report.percent is None; diff = '\n'.join(['--- a/tools/some_tool.py', '+++ b/tools/some_tool.py', '@@ -0,0 +1 @@', '+x = 1', '']); diff_file = _write(tmp_path, 'changes.diff', diff); result = subprocess.run([sys.executable, str(CLI), '--repo-root', str(tmp_path), '--diff-file', str(diff_file)], capture_output=True, text=True, cwd=REPO_ROOT); assert result.returncode == 0; assert re.search('(?i)warning.*tools', result.stdout + result.stderr); assert re.search('(?i)no measurable changed lines', result.stdout)
def _cli_fixture(tmp_path: Path) -> Path: _common_lcov(tmp_path, '\n'.join(['SF:common/pkg/mod.py', 'DA:45,0', 'DA:50,1', 'DA:51,1', 'DA:52,2', 'DA:60,4', 'end_of_record', ''])); _write(tmp_path, 'common/pkg/newmod.py', 'import sys\nprint(sys.argv)\n'); diff = '\n'.join(['--- a/common/pkg/mod.py', '+++ b/common/pkg/mod.py', '@@ -44,0 +45 @@', '+bad = 1', '@@ -49,2 +50,3 @@', '+ok = 1', '+ok = 2', '+ok = 3', '@@ -59 +60 @@', '+ok = 4', '--- /dev/null', '+++ b/common/pkg/newmod.py', '@@ -0,0 +1,2 @@', '+import sys', '+print(sys.argv)', '']); return _write(tmp_path, 'changes.diff', diff)
def _run_cli(tmp_path: Path, diff_file: Path, *args: str, env: dict | None = None):
    import contextlib
    import io
    import os
    from types import SimpleNamespace

    prev_env = os.environ.copy()
    out_buf = io.StringIO()
    err_buf = io.StringIO()
    try:
        if env:
            os.environ.update(env)
        with contextlib.redirect_stdout(out_buf), contextlib.redirect_stderr(err_buf):
            rc = dc.main(["--repo-root", str(tmp_path), "--diff-file", str(diff_file), *args])
    finally:
        os.environ.clear()
        os.environ.update(prev_env)
    return SimpleNamespace(returncode=rc, stdout=out_buf.getvalue(), stderr=err_buf.getvalue())
def test_cli_blocks_below_threshold_and_passes_at_or_above(tmp_path): 'AC-testing.diff-coverage.1'; diff_file = _cli_fixture(tmp_path); red = _run_cli(tmp_path, diff_file, '--threshold', '85'); assert red.returncode == 1; assert re.search('diff coverage: 57\\.1% \\(4/7 measurable changed lines covered\\)', red.stdout); assert re.search('threshold 85', red.stdout); green = _run_cli(tmp_path, diff_file, '--threshold', '50'); assert green.returncode == 0; at_threshold = _run_cli(tmp_path, diff_file, '--threshold', '57.1'); assert at_threshold.returncode == 0; env_red = _run_cli(tmp_path, diff_file, env={'DIFF_COVERAGE_THRESHOLD': '90'}); assert env_red.returncode == 1; env_green = _run_cli(tmp_path, diff_file, env={'DIFF_COVERAGE_THRESHOLD': '50'}); assert env_green.returncode == 0
def test_red_verdict_lists_uncovered_line_ranges_and_new_file_hole(tmp_path): 'AC-testing.diff-coverage.2'; diff_file = _cli_fixture(tmp_path); result = _run_cli(tmp_path, diff_file, '--threshold', '85'); assert result.returncode == 1; assert re.search('common/pkg/mod\\.py: uncovered lines 45', result.stdout); assert re.search('common/pkg/newmod\\.py: uncovered lines 1-2', result.stdout); assert re.search('(?i)not in .*lcov|zero tests', result.stdout); _m12_tmp = tmp_path / '_m12'; _m12_tmp.mkdir(exist_ok=True); _m12_root = _tiny_git_repo(_m12_tmp); _m12_result = subprocess.run([sys.executable, str(CLI), '--repo-root', str(_m12_root), '--base', 'main', '--threshold', '85'], capture_output=True, text=True, cwd=REPO_ROOT); assert _m12_result.returncode == 0; assert re.search('diff coverage: 100\\.0% \\(2/2 measurable changed lines covered\\)', _m12_result.stdout); _m13_tmp = tmp_path / '_m13'; _m13_tmp.mkdir(exist_ok=True); _m13_result = _run_cli(_m13_tmp, _m13_tmp / 'does-not-exist.diff'); assert _m13_result.returncode == 2; _m14_tmp = tmp_path / '_m14'; _m14_tmp.mkdir(exist_ok=True); _m14_code = _main_code(['--repo-root', str(_m14_tmp), '--diff-file', str(_m14_tmp / 'nope.diff')]); assert _m14_code == 2
def _tiny_git_repo(tmp_path: Path) -> Path:
    root = tmp_path / 'repo'; root.mkdir()
    def git(*args: str) -> None: subprocess.run(['git', '-C', str(root), *args], check=True, capture_output=True, env={'GIT_AUTHOR_NAME': 't', 'GIT_AUTHOR_EMAIL': 't@example.com', 'GIT_COMMITTER_NAME': 't', 'GIT_COMMITTER_EMAIL': 't@example.com', 'PATH': __import__('os').environ['PATH'], 'HOME': str(tmp_path)})
    git('init', '-b', 'main'); _write(root, 'common/pkg/mod.py', 'a = 1\n'); git('add', '.'); git('commit', '-m', 'base'); git('checkout', '-b', 'feature'); _write(root, 'common/pkg/mod.py', 'a = 1\nb = 2\nc = 3\n'); git('add', '.'); git('commit', '-m', 'change'); _common_lcov(root, 'SF:common/pkg/mod.py\nDA:1,1\nDA:2,1\nDA:3,1\nend_of_record\n'); return root
_main_code = lambda argv: dc.main(argv)
def test_main_red_then_green_thresholds(tmp_path, capfd): diff_file = _cli_fixture(tmp_path); base_args = ['--repo-root', str(tmp_path), '--diff-file', str(diff_file)]; assert _main_code([*base_args, '--threshold', '85']) == 1; out = capfd.readouterr().out; assert re.search('diff coverage: 57\\.1% \\(4/7 measurable changed lines covered\\)', out); assert re.search('common/pkg/mod\\.py: uncovered lines 45', out); assert re.search('common/pkg/newmod\\.py: uncovered lines 1-2', out); assert re.search('(?i)zero tests', out); assert _main_code([*base_args, '--threshold', '50']) == 0; assert re.search('✅ diff coverage', capfd.readouterr().out)
def test_main_env_threshold_fallback_and_validation(tmp_path, monkeypatch): diff_file = _cli_fixture(tmp_path); base_args = ['--repo-root', str(tmp_path), '--diff-file', str(diff_file)]; monkeypatch.setenv('DIFF_COVERAGE_THRESHOLD', '90'); assert _main_code(base_args) == 1; monkeypatch.setenv('DIFF_COVERAGE_THRESHOLD', '50'); assert _main_code(base_args) == 0; monkeypatch.setenv('DIFF_COVERAGE_THRESHOLD', 'not-a-number'); assert _main_code(base_args) == 2
def test_main_no_measurable_lines_passes_with_warning(tmp_path, capfd): _write(tmp_path, 'tools/some_tool.py', 'x = 1\n'); diff_file = _write(tmp_path, 'changes.diff', '\n'.join(['--- a/tools/some_tool.py', '+++ b/tools/some_tool.py', '@@ -0,0 +1 @@', '+x = 1', ''])); code = _main_code(['--repo-root', str(tmp_path), '--diff-file', str(diff_file)]); out = capfd.readouterr().out; assert code == 0; assert re.search('(?i)warning.*tools', out); assert re.search('(?i)no measurable changed lines', out)
def test_main_git_mode_and_bad_base(tmp_path, capfd, monkeypatch): root = _tiny_git_repo(tmp_path); monkeypatch.setenv('DIFF_COVERAGE_BASE', 'main'); assert _main_code(['--repo-root', str(root), '--threshold', '85']) == 0; assert re.search('diff coverage: 100\\.0% \\(2/2 measurable changed lines covered\\)', capfd.readouterr().out); monkeypatch.delenv('DIFF_COVERAGE_BASE'); code = _main_code(['--repo-root', str(root), '--base', 'no-such-ref', '--threshold', '85']); assert code == 2; assert re.search("(?i)git diff against 'no-such-ref' failed", capfd.readouterr().err)
